@@ -1544,7 +1544,9 @@ static float smin_set(const float* vals, int n, float fmin, float k) {
     if (k <= 1e-5f || n == 1) return fmin;
     float sum = 0.0f;
     for (int i = 0; i < n; ++i) sum += expf(-(vals[i] - fmin) / k);
